(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   井下复杂事故前兆预警 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  多变量异常检测：10+ 通道 → 综合异常分数\n   屏 2  不均衡处理：异常样本极少 → 重采样/SMOTE 补少数类\n   屏 3  可解释预警：报警 + 通道贡献 + 复核回流\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var CHANNELS = ['扭矩', '立压', '流量', '转速'];\n    var FAULTS = ['卡钻', '井漏', '溢流'];\n\n    /* -----------------------------------------------------\n       合成正常多通道时序\n       每通道有基线 + 波动 + 漂移。返回 { n, data: [chan][t] }\n       ----------------------------------------------------- */\n    function genChannels(n, seed) {\n      var rnd = mulberry32(seed || 20261141);\n      var nc = CHANNELS.length;\n      var base = [6, 15, 22, 55];   /* 扭矩/立压/流量/转速 基线 */\n      var amp = [0.5, 0.8, 0.7, 2.5];\n      var data = [];\n      for (var c = 0; c < nc; c++) {\n        data[c] = new Float64Array(n);\n        for (var t = 0; t < n; t++) {\n          data[c][t] = clamp(base[c] + Math.sin(t * 0.05 + c) * amp[c] * 0.4 + (rnd() - 0.5) * amp[c], 0.5, 70);\n        }\n      }\n      return { n: n, data: data };\n    }\n\n    /* -----------------------------------------------------\n       注入异常前兆\n       type 0 卡钻(扭矩↑立压↑流量↓) 1 井漏(流量↑立压↓) 2 溢流(立压↑流量↑)\n       在 idx 位置注入一段前兆。返回注入后的通道（拷贝）。\n       ----------------------------------------------------- */\n    function injectAnomaly(channels, idx, type, strength, seed) {\n      var rnd = mulberry32(seed || 20261142);\n      var n = channels.n, nc = channels.data.length;\n      var out = [];\n      for (var c = 0; c < nc; c++) { out[c] = new Float64Array(n); out[c].set(channels.data[c]); }\n      var w = 8;\n      for (var t = 0; t < w; t++) {\n        var p = t / (w - 1);\n        var env = Math.sin(p * Math.PI) * strength;\n        if (type === 0) { out[0][idx + t] += env * 2.5; out[1][idx + t] += env * 2.2; out[2][idx + t] -= env * 1.8; }\n        else if (type === 1) { out[1][idx + t] -= env * 2.4; out[2][idx + t] += env * 2.0; }\n        else { out[1][idx + t] += env * 2.2; out[2][idx + t] += env * 1.8; }\n        for (c = 0; c < nc; c++) out[c][idx + t] = clamp(out[c][idx + t], 0.5, 70);\n      }\n      return { n: n, data: out };\n    }\n\n    /* -----------------------------------------------------\n       多变量异常检测\n       滑动窗口内各通道偏离自身基线 → 综合异常分数（0..1）。\n       window：窗口大小。返回 { score: [t], contrib: [chan][t] }\n       ----------------------------------------------------- */\n    function detectAnomaly(channels, window, thr, base) {\n      var n = channels.n, nc = channels.data.length;\n      var win = window || 5;\n      var score = new Float64Array(n);\n      var contrib = [];\n      for (var c = 0; c < nc; c++) contrib[c] = new Float64Array(n);\n      /* 基线统计量：优先用正常通道（base），否则用当前通道（被异常稀释） */\n      var src = base || channels;\n      var mean = [], sd = [];\n      for (c = 0; c < nc; c++) {\n        var m = 0;\n        for (var t = 0; t < n; t++) m += src.data[c][t];\n        m /= n;\n        var v = 0;\n        for (t = 0; t < n; t++) v += (src.data[c][t] - m) * (src.data[c][t] - m);\n        mean.push(m); sd.push(Math.sqrt(v / n) + 1e-6);\n      }\n      for (t = 0; t < n; t++) {\n        var s = 0;\n        for (c = 0; c < nc; c++) {\n          /* 滑动窗口均值偏离 */\n          var wm = 0;\n          var cnt = 0;\n          for (var k = Math.max(0, t - win); k <= Math.min(n - 1, t + win); k++) { wm += channels.data[c][k]; cnt++; }\n          wm /= cnt;\n          var z = Math.abs(wm - mean[c]) / sd[c];\n          var contribC = clamp((z - 1.5) / 3, 0, 1);\n          contrib[c][t] = contribC;\n          s += contribC * contribC;\n        }\n        score[t] = clamp(Math.sqrt(s / nc), 0, 1);\n      }\n      return { score: score, contrib: contrib, thr: thr || 0.5 };\n    }\n\n    /* 预警事件：分数超阈值段 */\n    function alertEvents(score, thr) {\n      var n = score.length;\n      var evts = [];\n      var inAlert = false;\n      var start = 0;\n      for (var t = 0; t < n; t++) {\n        if (score[t] >= thr && !inAlert) { inAlert = true; start = t; }\n        if (score[t] < thr && inAlert) { inAlert = false; evts.push({ start: start, end: t - 1 }); }\n      }\n      if (inAlert) evts.push({ start: start, end: n - 1 });\n      return evts;\n    }\n\n    /* -----------------------------------------------------\n       不均衡处理\n       少数类（异常）比例极低。method：none/upsample/smote。\n       返回合成后的样本比例 + 检测召回改善因子。\n       ----------------------------------------------------- */\n    function balanceTrain(anomalyRatio, method, seed) {\n      var rnd = mulberry32(seed || 20261143);\n      var ratio = clamp(anomalyRatio, 0.001, 0.5);\n      var outRatio;\n      if (method === 'none') outRatio = ratio;\n      else if (method === 'upsample') outRatio = clamp(ratio * (1.5 + rnd() * 1.5), 0.05, 0.35);\n      else outRatio = clamp(ratio * (2.5 + rnd() * 1.5), 0.1, 0.4);\n      /* 召回改善因子：均衡越好召回越高 */\n      var recall = clamp(0.4 + outRatio * 1.2, 0.4, 0.95);\n      var falseRate = clamp(0.35 - outRatio * 0.6, 0.05, 0.35);\n      return { ratioIn: ratio, ratioOut: outRatio, method: method, recall: recall, falseRate: falseRate };\n    }\n\n    /* -----------------------------------------------------\n       可解释预警\n       对一次预警事件，算各通道贡献度 + 触发时刻。返回解释。\n       ----------------------------------------------------- */\n    function explainAlert(channels, contrib, evt) {\n      var nc = channels.data.length;\n      var contribSum = new Float64Array(nc);\n      var peakT = evt.start, peakV = -1;\n      for (var t = evt.start; t <= evt.end; t++) {\n        for (var c = 0; c < nc; c++) contribSum[c] += contrib[c][t];\n        var s = 0;\n        for (c = 0; c < nc; c++) s += contrib[c][t];\n        if (s > peakV) { peakV = s; peakT = t; }\n      }\n      var total = 0;\n      for (c = 0; c < nc; c++) total += contribSum[c];\n      var per = [];\n      for (c = 0; c < nc; c++) per.push({ chan: CHANNELS[c], weight: total > 0 ? contribSum[c] / total : 0 });\n      per.sort(function (a, b) { return b.weight - a.weight; });\n      return { channels: per, peakT: peakT, duration: evt.end - evt.start + 1 };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32, CHANNELS: CHANNELS, FAULTS: FAULTS,\n      genChannels: genChannels, injectAnomaly: injectAnomaly,\n      detectAnomaly: detectAnomaly, alertEvents: alertEvents,\n      balanceTrain: balanceTrain, explainAlert: explainAlert\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = {\n    faultType: 0, strength: 0.7, thr: 0.5, window: 5,\n    balMethod: 1 /* 0 none 1 upsample 2 smote */, anomalyRatio: 0.01\n  };\n\n  var chan1 = M.genChannels(60, 20261141);\n  var noisy1 = M.injectAnomaly(chan1, 40, state.faultType, state.strength, 20261142);\n  var det1 = M.detectAnomaly(noisy1, state.window, state.thr);\n\n  global.RemoteBridge = {\n    M: M,\n    genChannels: M.genChannels, injectAnomaly: M.injectAnomaly,\n    detectAnomaly: M.detectAnomaly, alertEvents: M.alertEvents,\n    balanceTrain: M.balanceTrain, explainAlert: M.explainAlert,\n    live: function () {\n      return { faultType: state.faultType, strength: state.strength, thr: state.thr, window: state.window, balMethod: state.balMethod, anomalyRatio: state.anomalyRatio };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  function linePath(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 屏 1 渲染：多变量异常检测 ---------- */\n  function renderDetect() {\n    chan1 = M.genChannels(60, 20261141);\n    noisy1 = M.injectAnomaly(chan1, 40, state.faultType, state.strength, 20261142);\n    det1 = M.detectAnomaly(noisy1, state.window, state.thr, chan1);\n    var evts = M.alertEvents(det1.score, state.thr);\n    var n = 60, H = 90, x0 = 30, y0 = 18;\n    var xS = 360 / n;\n\n    /* 多通道时序（层叠） */\n    var s = '';\n    var colors = ['#b26a39', '#41699b', '#2f7d6b', '#6b7a6b'];\n    for (var c = 0; c < 4; c++) {\n      var ch = noisy1.data[c];\n      /* 通道值范围归一化到 0..1 */\n      var minV = Infinity, maxV = -Infinity;\n      for (var t = 0; t < n; t++) { if (ch[t] < minV) minV = ch[t]; if (ch[t] > maxV) maxV = ch[t]; }\n      var span = (maxV - minV) || 1;\n      var arr = [];\n      for (t = 0; t < n; t++) arr.push((ch[t] - minV) / span);\n      var yBase = y0 + c * 24 + 14;\n      s += '<text x=\"4\" y=\"' + (yBase + 3) + '\" font-size=\"7.5\" fill=\"' + colors[c] + '\" font-weight=\"700\">' + M.CHANNELS[c] + '<\/text>';\n      s += linePath(arr, x0, yBase, xS, 20, colors[c], false);\n    }\n    /* 异常前兆区 */\n    var injStart = 40, injW = 8;\n    s += '<rect x=\"' + (x0 + injStart * xS) + '\" y=\"' + (y0 - 2) + '\" width=\"' + (injW * xS) + '\" height=\"' + (4 * 24 + 8) + '\" fill=\"#f5d9d4\" opacity=\"0.5\" stroke=\"#b05a51\" stroke-width=\"1\"/>';\n    s += '<text x=\"' + (x0 + (injStart + injW / 2) * xS) + '\" y=\"' + (y0 - 4) + '\" font-size=\"8\" fill=\"#b05a51\" text-anchor=\"middle\" font-weight=\"700\">' + M.FAULTS[state.faultType] + '前兆<\/text>';\n    $('chanChart').innerHTML = s;\n\n    /* 异常分数曲线 */\n    var sy0 = 210, sH = 80;\n    var s2 = '<text x=\"30\" y=\"' + (sy0 - 8) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">综合异常分数<\/text>';\n    s2 += '<line x1=\"30\" y1=\"' + (sy0 + sH) + '\" x2=\"' + (30 + 360) + '\" y2=\"' + (sy0 + sH) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    /* 阈值线 */\n    s2 += '<line x1=\"30\" y1=\"' + (sy0 + sH - state.thr * sH) + '\" x2=\"' + (30 + 360) + '\" y2=\"' + (sy0 + sH - state.thr * sH) + '\" stroke=\"#b05a51\" stroke-width=\"1.2\" stroke-dasharray=\"4 3\"/>';\n    s2 += '<text x=\"392\" y=\"' + (sy0 + sH - state.thr * sH + 3) + '\" font-size=\"7.5\" fill=\"#b05a51\">阈值 ' + num(state.thr, 2) + '<\/text>';\n    var score = det1.score;\n    var arrS = [];\n    for (t = 0; t < n; t++) arrS.push(score[t]);\n    s2 += linePath(arrS, 30, sy0 + sH, xS, sH, '#24333a', false);\n    /* 预警事件标记 */\n    evts.forEach(function (e) {\n      s2 += '<rect x=\"' + (30 + e.start * xS) + '\" y=\"' + (sy0 + sH - 90) + '\" width=\"' + ((e.end - e.start + 1) * xS) + '\" height=\"90\" fill=\"#2f7d6b\" opacity=\"0.18\"/>';\n    });\n    $('scoreChart').innerHTML = s2;\n\n    $('roEvts').textContent = evts.length + ' 个预警事件';\n    $('roFault').textContent = M.FAULTS[state.faultType];\n  }\n\n  /* ---------- 屏 2 渲染：不均衡处理 ---------- */\n  function renderBalance() {\n    var methods = ['none', 'upsample', 'smote'];\n    var method = methods[state.balMethod];\n    var r = M.balanceTrain(state.anomalyRatio, method, 20261143);\n    /* 柱状：正常 vs 异常 比例 */\n    var x0 = 40, y0 = 40, bw = 240;\n    var s = '';\n    /* 处理前 */\n    s += '<text x=\"40\" y=\"26\" font-size=\"9.5\" fill=\"#4d565b\" font-weight=\"700\">处理前：正常 ' + (1 - r.ratioIn) + ' · 异常 ' + r.ratioIn + '<\/text>';\n    s += '<rect x=\"' + x0 + '\" y=\"' + y0 + '\" width=\"' + (bw * (1 - r.ratioIn)) + '\" height=\"26\" fill=\"#7a8a9a\"/>';\n    s += '<rect x=\"' + (x0 + bw * (1 - r.ratioIn)) + '\" y=\"' + y0 + '\" width=\"' + (bw * r.ratioIn) + '\" height=\"26\" fill=\"#b05a51\"/>';\n    /* 处理后 */\n    var label = method === 'none' ? '不处理' : method === 'upsample' ? '重采样' : 'SMOTE 合成';\n    s += '<text x=\"40\" y=\"' + (y0 + 52) + '\" font-size=\"9.5\" fill=\"#4d565b\" font-weight=\"700\">' + label + '后：正常 ' + (1 - r.ratioOut).toFixed(2) + ' · 异常 ' + r.ratioOut.toFixed(2) + '<\/text>';\n    s += '<rect x=\"' + x0 + '\" y=\"' + (y0 + 62) + '\" width=\"' + (bw * (1 - r.ratioOut)) + '\" height=\"26\" fill=\"#7a8a9a\"/>';\n    s += '<rect x=\"' + (x0 + bw * (1 - r.ratioOut)) + '\" y=\"' + (y0 + 62) + '\" width=\"' + (bw * r.ratioOut) + '\" height=\"26\" fill=\"#2f7d6b\"/>';\n\n    /* 召回 vs 误报 */\n    var gx = 40, gy = 180;\n    s += '<rect x=\"' + gx + '\" y=\"' + gy + '\" width=\"180\" height=\"26\" rx=\"4\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/>';\n    s += '<text x=\"' + (gx + 10) + '\" y=\"' + (gy + 18) + '\" font-size=\"8.5\" fill=\"#22604f\" font-weight=\"700\">召回 ' + Math.round(r.recall * 100) + '%<\/text>';\n    s += '<rect x=\"' + (gx + 200) + '\" y=\"' + gy + '\" width=\"180\" height=\"26\" rx=\"4\" fill=\"#f7ece2\" stroke=\"#b26a39\"/>';\n    s += '<text x=\"' + (gx + 210) + '\" y=\"' + (gy + 18) + '\" font-size=\"8.5\" fill=\"#8a4f27\" font-weight=\"700\">误报率 ' + Math.round(r.falseRate * 100) + '%<\/text>';\n    $('balChart').innerHTML = s;\n    $('roBalMethod').textContent = label + '：异常比例 ' + r.ratioIn.toFixed(3) + ' → ' + r.ratioOut.toFixed(3);\n    $('roRecall').textContent = '召回 ' + Math.round(r.recall * 100) + '%';\n  }\n\n  /* ---------- 屏 3 渲染：可解释预警 ---------- */\n  function renderExplain() {\n    chan1 = M.genChannels(60, 20261141);\n    noisy1 = M.injectAnomaly(chan1, 40, state.faultType, state.strength, 20261142);\n    det1 = M.detectAnomaly(noisy1, state.window, state.thr, chan1);\n    var evts = M.alertEvents(det1.score, state.thr);\n    var s = '';\n    if (evts.length === 0) {\n      s = '<text x=\"40\" y=\"40\" font-size=\"10\" fill=\"#9ba3a9\">无预警（阈值过高或异常太弱）<\/text>';\n      $('explChart').innerHTML = s;\n      $('roExplain').textContent = '无预警';\n      return;\n    }\n    var evt = evts[0];\n    var exp = M.explainAlert(noisy1, det1.contrib, evt);\n    /* 通道贡献条形 */\n    var y = 24;\n    var maxW = Math.max.apply(null, exp.channels.map(function (c) { return c.weight; })) || 1;\n    for (var i = 0; i < exp.channels.length; i++) {\n      var c = exp.channels[i];\n      var w = (c.weight / maxW) * 260;\n      var col = i < 2 ? '#b05a51' : '#7a8a9a';\n      s += '<text x=\"40\" y=\"' + (y + 12) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">' + c.chan + '<\/text>';\n      s += '<rect x=\"90\" y=\"' + y + '\" width=\"' + w + '\" height=\"18\" rx=\"3\" fill=\"' + col + '\"/>';\n      s += '<text x=\"' + (90 + w + 6) + '\" y=\"' + (y + 14) + '\" font-size=\"8.5\" fill=\"#4d565b\">' + Math.round(c.weight * 100) + '%<\/text>';\n      y += 30;\n    }\n    s += '<text x=\"40\" y=\"' + (y + 16) + '\" font-size=\"9\" fill=\"#24333a\" font-weight=\"700\">触发时刻：第 ' + (exp.peakT + 1) + ' 个采样点 · 持续 ' + exp.duration + ' 点<\/text>';\n    s += '<text x=\"40\" y=\"' + (y + 34) + '\" font-size=\"8.5\" fill=\"#8a4f27\">' + M.FAULTS[state.faultType] + '前兆：' + exp.channels[0].chan + '↑ / ' + exp.channels[1].chan + '↑<\/text>';\n    $('explChart').innerHTML = s;\n    $('roExplain').textContent = '预警：' + M.FAULTS[state.faultType] + ' · 主因 ' + exp.channels[0].chan + ' ' + Math.round(exp.channels[0].weight * 100) + '%';\n    /* 复核清单 */\n    var cls = [];\n    var rows = [\n      ['前兆事件', M.FAULTS[state.faultType], '真前兆'],\n      ['时刻', '第 ' + (exp.peakT + 1) + ' 点', 'ok'],\n      ['处置', '已反馈', 'ok']\n    ];\n    var rs = '';\n    for (var r = 0; r < rows.length; r++) {\n      rs += '<div class=\"row\"><span>' + rows[r][0] + '<\/span><b>' + rows[r][1] + '<\/b><em>' + rows[r][2] + '<\/em><\/div>';\n    }\n    var revEl = $('reviewList');\n    if (revEl) revEl.innerHTML = rs;\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inFault = $('inFault');\n    if (inFault) inFault.addEventListener('input', function () {\n      state.faultType = parseInt(inFault.value, 10);\n      $('outFault').textContent = M.FAULTS[state.faultType];\n      renderDetect(); renderExplain();\n    });\n    var inStr = $('inStr');\n    if (inStr) inStr.addEventListener('input', function () {\n      state.strength = parseFloat(inStr.value);\n      $('outStr').textContent = num(state.strength, 2);\n      renderDetect(); renderExplain();\n    });\n    var inThr = $('inThr');\n    if (inThr) inThr.addEventListener('input', function () {\n      state.thr = parseFloat(inThr.value);\n      $('outThr').textContent = num(state.thr, 2);\n      renderDetect(); renderExplain();\n    });\n    var inMethod = $('inMethod');\n    if (inMethod) inMethod.addEventListener('input', function () {\n      state.balMethod = parseInt(inMethod.value, 10);\n      var labels = ['不处理', '重采样', 'SMOTE'];\n      $('outMethod').textContent = labels[state.balMethod];\n      renderBalance();\n    });\n    var inRatio = $('inRatio');\n    if (inRatio) inRatio.addEventListener('input', function () {\n      state.anomalyRatio = parseFloat(inRatio.value);\n      $('outRatio').textContent = num(state.anomalyRatio, 3);\n      renderBalance();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '异常检测', 'detCtl'], ['sec2', '不均衡处理', 'balCtl'], ['sec3', '可解释预警', 'explCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      el.querySelectorAll('input, button').forEach(function (c) {\n        if (c.type === 'range') c.setAttribute('value', c.value);\n      });\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderDetect(); renderBalance(); renderExplain();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   井下复杂事故前兆预警 · 算法解剖（多变量异常 + 不均衡 + 可解释）\n   ---------------------------------------------------------\n   把「多通道 → 事故前兆预警」拆成 6 步，每一步都跑真代码：\n\n     ① 数据接入      多通道 + 工况标注\n     ② 异常标注      事故点 → 异常前兆段（极少）\n     ③ 异常检测      多通道 → 综合异常分数\n     ④ 不均衡处理    重采样 / SMOTE 补少数类\n     ⑤ 可解释预警    报警 + 通道贡献 + 触发时刻\n     ⑥ 复核与回流    真前兆/误报 → 模型改进\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var N = 60, x0 = 30, xS = 360 / N;\n  var CH_COLORS = ['#b26a39', '#41699b', '#2f7d6b', '#6b7a6b'];\n\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  function chanLine(chan, y0, H, color) {\n    var s = '';\n    var minV = Infinity, maxV = -Infinity;\n    for (var t = 0; t < N; t++) { if (chan[t] < minV) minV = chan[t]; if (chan[t] > maxV) maxV = chan[t]; }\n    var span = (maxV - minV) || 1;\n    s += '<path d=\"M';\n    for (t = 0; t < N; t++) {\n      var v = (chan[t] - minV) / span;\n      s += (x0 + t * xS).toFixed(1) + ' ' + (y0 + H - v * H).toFixed(1);\n      if (t < N - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"1.8\"/>';\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.faultType, L.strength, L.thr, L.window, L.balMethod, L.anomalyRatio].join(',');\n    if (cache.key === key) return cache;\n    var chan = M.genChannels(N, 20261141);\n    var noisy = M.injectAnomaly(chan, 40, L.faultType, L.strength, 20261142);\n    var det = M.detectAnomaly(noisy, L.window, L.thr, chan);\n    var evts = M.alertEvents(det.score, L.thr);\n    var bal = M.balanceTrain(L.anomalyRatio, ['none', 'upsample', 'smote'][L.balMethod], 20261143);\n    var expl = evts.length ? M.explainAlert(noisy, det.contrib, evts[0]) : null;\n    cache = { key: key, L: L, chan: chan, noisy: noisy, det: det, evts: evts, bal: bal, expl: expl };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 数据接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), L = c.L;\n    var s = '';\n    s += G.panel(0, '① 多通道', '扭矩/立压/流量/转速', C.clay);\n    s += G.panel(1, '② 工况标注', '正常钻进/起下钻', C.blue);\n    s += G.panel(2, '③ 排除假异常', '工况切换', C.jade);\n\n    var y0 = 130;\n    s += G.txt(x0, y0 - 20, '10+ 随钻通道时序（扭矩/立压/流量/转速）', { size: 9.5, fill: C.ink2, weight: 700 });\n    for (var c2 = 0; c2 < 4; c2++) {\n      s += chanLine(c.noisy.data[c2], y0 + c2 * 44, 40, CH_COLORS[c2]);\n      s += G.txt(4, y0 + c2 * 44 + 40, M.CHANNELS[c2], { size: 7.5, fill: CH_COLORS[c2], weight: 700 });\n    }\n\n    s += footBox(420, 170, 120, 180, '为什么要工况标注',\n      ['· 正常钻进/起下钻参数',\n       '  本身变化大',\n       '· 不排除工况切换 →',\n       '  正常变化当异常',\n       '',\n       '误报爆表，现场',\n       '疲于应付。'], 'blue');\n    return { svg: s, stats: [{ k: '通道', v: '10+' }, { k: '工况', v: '正常钻进/起下钻' }, { k: '目标', v: '排假异常' }], note: '读入随钻多通道时序，按工况标注正常钻进/起下钻。不排除工况切换，会把正常起下钻的参数变化当异常，误报爆表。' };\n  }\n\n  /* =========================================================\n     ② 异常标注\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), L = c.L;\n    var s = '';\n    s += G.panel(0, '① 事故发生点', '卡钻/井漏/溢流', C.clay);\n    s += G.panel(1, '② 前兆段标注', '极少样本', C.blue);\n    s += G.panel(2, '③ 类不均衡', '异常≈1%', C.jade);\n\n    var y0 = 130;\n    s += G.txt(x0, y0 - 20, M.FAULTS[L.faultType] + '前兆（注入强度 ' + f(L.strength, 2) + '）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var injStart = 40, injW = 8;\n    s += G.rect(x0 + injStart * xS, y0 - 4, injW * xS, 4 * 44 + 8, { fill: '#f5d9d4', op: 0.5, stroke: '#b05a51' });\n    for (var c2 = 0; c2 < 4; c2++) {\n      s += chanLine(c.noisy.data[c2], y0 + c2 * 44, 40, CH_COLORS[c2]);\n      s += G.txt(4, y0 + c2 * 44 + 40, M.CHANNELS[c2], { size: 7.5, fill: CH_COLORS[c2], weight: 700 });\n    }\n    s += G.txt(x0 + (injStart + injW / 2) * xS, y0 - 4, M.FAULTS[L.faultType] + '前兆', { size: 8, fill: '#b05a51', anchor: 'middle', weight: 700 });\n\n    s += footBox(420, 170, 120, 180, '标注难点',\n      ['· 事故本身少',\n       '· 异常前兆样本极少',\n       '· 类不均衡 ≈ 1%',\n       '',\n       '边界模糊的正常段',\n       '别标成异常，否则',\n       '模型更分不清。'], 'clay');\n    return { svg: s, stats: [{ k: '事故类型', v: M.FAULTS[L.faultType] }, { k: '前兆强度', v: f(L.strength, 2) }, { k: '异常占比', v: '≈1%' }], note: '把卡钻/井漏/溢流发生点前的异常前兆段标注出来。异常样本太少又不想漏，把边界模糊的正常段也标成异常，模型更分不清。' };\n  }\n\n  /* =========================================================\n     ③ 多变量异常检测\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), det = c.det, evts = c.evts, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 多通道', '10+ 通道', C.blue);\n    s += G.panel(1, '② 重建误差', '多变量联合', C.jade);\n    s += G.panel(2, '③ 异常分数', '组合前兆', C.clay);\n\n    var y0 = 130;\n    s += G.txt(x0, y0 - 20, '综合异常分数（窗口 ' + L.window + ' · 阈值 ' + f(L.thr, 2) + '）', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, 360, 160, { nx: 4, ny: 3 });\n    var arrS = [];\n    for (var t = 0; t < N; t++) arrS.push(det.score[t]);\n    s += '<path d=\"M';\n    for (t = 0; t < N; t++) {\n      s += (x0 + t * xS).toFixed(1) + ' ' + (y0 + 160 - det.score[t] * 150).toFixed(1);\n      if (t < N - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"#24333a\" stroke-width=\"2\"/>';\n    s += G.line(x0, y0 + 160 - L.thr * 150, x0 + 360, y0 + 160 - L.thr * 150, { stroke: '#b05a51', sw: 1.2, dash: '4 3' });\n    s += G.txt(x0 + 362, y0 + 160 - L.thr * 150 + 3, '阈值 ' + f(L.thr, 2), { size: 7.5, fill: '#b05a51' });\n    evts.forEach(function (e) {\n      s += G.rect(x0 + e.start * xS, y0 + 160 - 170, (e.end - e.start + 1) * xS, 170, { fill: '#2f7d6b', op: 0.18 });\n    });\n\n    s += footBox(420, 170, 130, 176, '为什么多变量',\n      ['· 前兆是多通道组合变化',\n       '· 单通道阈值抓不住',\n       '· 重建误差联合建模',\n       '',\n       evts.length + ' 个预警事件',\n       '漏一个真前兆代价巨大。'], 'jade');\n    return { svg: s, stats: [{ k: '预警事件', v: evts.length + ' 个' }, { k: '阈值', v: f(L.thr, 2) }, { k: '窗口', v: L.window }], note: '用多变量异常检测从多通道算综合异常分数。只看单通道或只看均值，抓不住多个通道同时小幅偏离的组合前兆。' };\n  }\n\n  /* =========================================================\n     ④ 不均衡处理\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), bal = c.bal, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 类不均衡', '正常≈99%', C.clay);\n    s += G.panel(1, '② 重采样/SMOTE', '补少数类', C.jade);\n    s += G.panel(2, '③ 均衡后训练', '不偏向多数', C.blue);\n\n    var x0 = 40, y0 = 130, bw = 260;\n    s += G.txt(x0, y0 - 20, '处理前：正常 ' + (1 - bal.ratioIn) + ' · 异常 ' + bal.ratioIn, { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.rect(x0, y0, bw * (1 - bal.ratioIn), 24, { fill: '#7a8a9a', op: 1 });\n    s += G.rect(x0 + bw * (1 - bal.ratioIn), y0, bw * bal.ratioIn, 24, { fill: '#b05a51', op: 1 });\n    var label = bal.method === 'none' ? '不处理' : bal.method === 'upsample' ? '重采样' : 'SMOTE 合成';\n    s += G.txt(x0, y0 + 40, label + '后：正常 ' + (1 - bal.ratioOut).toFixed(2) + ' · 异常 ' + bal.ratioOut.toFixed(2), { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.rect(x0, y0 + 52, bw * (1 - bal.ratioOut), 24, { fill: '#7a8a9a', op: 1 });\n    s += G.rect(x0 + bw * (1 - bal.ratioOut), y0 + 52, bw * bal.ratioOut, 24, { fill: '#2f7d6b', op: 1 });\n\n    s += footBox(420, 150, 130, 170, '效果',\n      ['· 召回 ' + Math.round(bal.recall * 100) + '%',\n       '· 误报率 ' + Math.round(bal.falseRate * 100) + '%',\n       '',\n       'SMOTE 合成太假会',\n       '学到「合成异常」而非',\n       '真前兆 → 真事故照漏。'], 'clay');\n    return { svg: s, stats: [{ k: '方法', v: label }, { k: '异常比例', v: bal.ratioIn.toFixed(3) + '→' + bal.ratioOut.toFixed(3) }, { k: '召回', v: Math.round(bal.recall * 100) + '%' }], note: '异常样本极少，用重采样或 SMOTE 合成异常补少数类。SMOTE 合成异常太假，学到的是合成异常而非真前兆，真事故照漏。' };\n  }\n\n  /* =========================================================\n     ⑤ 可解释预警\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), expl = c.expl, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 异常分数', '超阈值触发', C.clay);\n    s += G.panel(1, '② 通道贡献', '立压↑ 流量↓', C.blue);\n    s += G.panel(2, '③ 可解释', '人敢处置', C.jade);\n\n    var x0 = 30, y0 = 130;\n    if (!expl) {\n      s += G.txt(x0, y0, '当前参数无预警事件，请调低阈值或加大异常强度。', { size: 9.5, fill: '#8a4f27' });\n      return { svg: s, stats: [{ k: '预警', v: '无' }], note: '当前无预警。请调低阈值或加大异常强度触发一次预警。' };\n    }\n    var maxW = Math.max.apply(null, expl.channels.map(function (cc) { return cc.weight; })) || 1;\n    for (var i = 0; i < expl.channels.length; i++) {\n      var cc = expl.channels[i];\n      var w = (cc.weight / maxW) * 260;\n      var col = i < 2 ? '#b05a51' : '#7a8a9a';\n      s += G.txt(x0, y0 + i * 34 + 14, cc.chan, { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.rect(x0 + 56, y0 + i * 34, w, 18, { r: 3, fill: col, op: 1 });\n      s += G.txt(x0 + 56 + w + 6, y0 + i * 34 + 14, Math.round(cc.weight * 100) + '%', { size: 8, fill: C.ink3 });\n    }\n    s += G.txt(x0, y0 + 4 * 34 + 8, '触发时刻：第 ' + (expl.peakT + 1) + ' 个采样点 · 持续 ' + expl.duration + ' 点', { size: 9, fill: C.ink2, weight: 700 });\n    s += G.txt(x0, y0 + 4 * 34 + 26, M.FAULTS[L.faultType] + '前兆：' + expl.channels[0].chan + '↑ / ' + expl.channels[1].chan + '↑', { size: 8.5, fill: '#8a4f27' });\n\n    s += footBox(420, 170, 130, 176, '可解释的价值',\n      ['· 黑盒报警不敢信',\n       '· 通道+时刻说清为什么',\n       '· 现场敢响应、能定位',\n       '',\n       '可解释若只是事后贴',\n       '标签，会误导处置。'], 'jade');\n    return { svg: s, stats: [{ k: '主因', v: expl.channels[0].chan + ' ' + Math.round(expl.channels[0].weight * 100) + '%' }, { k: '触发时刻', v: '第 ' + (expl.peakT + 1) + ' 点' }], note: '给预警附解释：哪几个通道贡献大、哪一段时序触发。可解释是事后贴标签、没反映真实判断依据时，会误导现场处置。' };\n  }\n\n  /* =========================================================\n     ⑥ 复核与回流\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), evts = c.evts, bal = c.bal, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 预警事件', '超阈值', C.blue);\n    s += G.panel(1, '② 复核真伪', '真前兆/误报', C.clay);\n    s += G.panel(2, '③ 反馈回流', '误报率下降', C.jade);\n\n    var x0 = 30, y0 = 130;\n    var rows = [];\n    if (evts.length) rows.push(['前兆预警', M.FAULTS[L.faultType], '真前兆']);\n    rows.push(['误报复查', '阈值波动段', '待核']);\n    rows.push(['处置反馈', '已响应', 'ok']);\n    rows.push(['召回提升', Math.round(bal.recall * 100) + '%', 'ok']);\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 36;\n      s += G.rect(x0, ry, 360, 28, { r: 4, fill: rows[r][2] === 'ok' ? C.jadeL : rows[r][2] === '待核' ? C.clayL : C.blueL, stroke: rows[r][2] === 'ok' ? '#b9d8cb' : rows[r][2] === '待核' ? '#e6cdb2' : '#c5d6ea' });\n      s += G.txt(x0 + 12, ry + 19, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(x0 + 110, ry + 19, rows[r][1], { size: 8.8, fill: rows[r][2] === 'ok' ? C.jadeD : '#8a4f27' });\n      s += G.txt(x0 + 320, ry + 19, rows[r][2], { size: 8.8, fill: rows[r][2] === 'ok' ? C.jadeD : '#8a4f27', weight: 700 });\n    }\n    s += G.txt(x0, y0 - 20, '预警复核与回流清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '闭环的意义',\n      ['· 复核结果反馈模型',\n       '· 误报率持续下降',\n       '· 预警越来越可信',\n       '',\n       '复核不回流 → 模型',\n       '不知道误报 → 误报率',\n       '永远降不下来。'], 'clay');\n    return { svg: s, stats: [{ k: '预警事件', v: evts.length + ' 个' }, { k: '误报率', v: Math.round(bal.falseRate * 100) + '%' }], note: '处理员对每次预警复核，结果反馈回模型。复核不回流，模型不知道误报，误报率永远降不下来。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：井下复杂事故前兆预警<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n.review-list{font-size:13px;border:1px solid #e9e4d8;border-radius:8px;overflow:hidden;margin-top:8px}\n.review-list .row{display:flex;align-items:center;padding:7px 12px;border-bottom:1px solid #f0ece2}\n.review-list .row:last-child{border-bottom:none}\n.review-list .row span{flex:1;color:#4d565b}\n.review-list .row b{width:180px;color:#24333a;font-weight:700}\n.review-list .row em{color:#2f7d6b;font-style:normal;font-weight:700;font-size:12px}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 钻井工程 / 井下复杂事故前兆预警<\/span>\n  <h1>从「单通道阈值 · 误报一堆」到「多变量异常 + 可解释预警」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂异常检测、Q2 不均衡处理、Q3 可解释预警。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 事故预警全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「多通道 → 黑盒 → 报警」，而是<b>逐段展开<\/b>：数据接入 → 异常标注 → 异常检测 → 不均衡处理 → 可解释预警 → 复核回流，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 3—5<\/span>\n    <h2>把「多通道 → 事故前兆预警」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改事故类型、异常强度、阈值，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（异常分数、不均衡效果、可解释预警）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>detectAnomaly / balanceTrain / explainAlert<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步用红框标出异常前兆段，看得见「极少异常样本」的对象；<b>②<\/b> 第 5 步把各通道的贡献度条形画出来，看得见预警「为什么」触发。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 多变量异常检测 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">单通道阈值误报高；多变量异常检测抓组合前兆<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 3<\/span>\n    <h2>多变量异常检测：10+ 通道 → 综合异常分数<\/h2>\n    <p class=\"leadline\">切事故类型与强度，拖阈值，看多通道时序怎么被压成综合异常分数、触发预警。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"detCtl\">\n    <div class=\"sl\">\n      <label>事故类型<output id=\"outFault\">卡钻<\/output><\/label>\n      <input type=\"range\" id=\"inFault\" min=\"0\" max=\"2\" step=\"1\" value=\"0\">\n    <\/div>\n    <div class=\"sl\">\n      <label>前兆强度<output id=\"outStr\">0.70<\/output><\/label>\n      <input type=\"range\" id=\"inStr\" min=\"0.2\" max=\"1\" step=\"0.05\" value=\"0.7\">\n    <\/div>\n    <div class=\"sl\">\n      <label>预警阈值<output id=\"outThr\">0.50<\/output><\/label>\n      <input type=\"range\" id=\"inThr\" min=\"0.2\" max=\"0.9\" step=\"0.05\" value=\"0.5\">\n    <\/div>\n  <\/div>\n  <svg id=\"chanChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"多通道时序\"><\/svg>\n  <svg id=\"scoreChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"综合异常分数\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">事故类型<\/span><b id=\"roFault\">卡钻<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">预警事件<\/span><b id=\"roEvts\" class=\"good\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"detTip\">三种事故前兆形态不同：卡钻是扭矩↑立压↑流量↓、井漏是流量↑立压↓、溢流是立压↑流量↑。多变量异常检测把它们联合建模，比单通道阈值更能抓「组合前兆」。阈值越高误报越少但漏报越多。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 不均衡处理 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>不均衡处理<\/b>：异常样本极少 → 重采样 / SMOTE 补少数类<span class=\"qa-algo\">多变量异常检测 · 不均衡<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 4<\/span>\n    <h2>不均衡处理：异常样本极少怎么办<\/h2>\n    <p class=\"leadline\">事故本身少，异常前兆样本 ≈ 1%。切处理方法与异常比例，看召回与误报怎么变。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"balCtl\">\n    <div class=\"sl\">\n      <label>处理方法<output id=\"outMethod\">重采样<\/output><\/label>\n      <input type=\"range\" id=\"inMethod\" min=\"0\" max=\"2\" step=\"1\" value=\"1\">\n    <\/div>\n    <div class=\"sl\">\n      <label>异常比例<output id=\"outRatio\">0.010<\/output><\/label>\n      <input type=\"range\" id=\"inRatio\" min=\"0.005\" max=\"0.2\" step=\"0.005\" value=\"0.01\">\n    <\/div>\n  <\/div>\n  <svg id=\"balChart\" viewBox=\"0 0 430 240\" role=\"img\" aria-label=\"不均衡处理对比\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">方法<\/span><b id=\"roBalMethod\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">召回<\/span><b id=\"roRecall\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"balTip\">不处理时模型偏向多数类（正常），异常前兆被淹没、召回低；重采样把少数异常类补上来、SMOTE 合成更多异常样本，召回提升。但合成异常太假会学到「合成异常」而非真前兆，真事故照漏。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 可解释预警 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">异常分数超阈值 → <b>可解释<\/b>（哪通道、哪时刻）→ 人敢处置 → 复核回流<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5—6<\/span>\n    <h2>可解释预警：说清「为什么」才敢处置<\/h2>\n    <p class=\"leadline\">黑盒报警现场不敢信。拖实验 1 的事故类型/强度/阈值，看预警解释了哪几个通道、哪一段时序触发。<\/p>\n  <\/div>\n  <svg id=\"explChart\" viewBox=\"0 0 440 200\" role=\"img\" aria-label=\"可解释预警\"><\/svg>\n  <div class=\"rrow ro1\">\n    <div class=\"ro\"><span class=\"k\">预警解释<\/span><b id=\"roExplain\" class=\"good\">—<\/b><\/div>\n  <\/div>\n  <div class=\"review-list\" id=\"reviewList\"><\/div>\n  <p class=\"tip\" id=\"explTip\">预警不仅报「有异常」，还说清哪几个通道贡献大（主因）、哪一段时序触发。现场据此定位处置；每次复核结果回流模型，误报率持续下降。可解释若是事后贴标签而非真实判断依据，会误导处置。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 3<\/b><br>多变量异常检测。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>不均衡处理补少数类。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>可解释预警 + 复核回流。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：随钻多通道时序由「正常基线 + 注入事故前兆」合成，事故点已知、仅供对比；多变量异常检测、不均衡处理与可解释预警均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：多通道怎么一步步变成事故前兆预警',\n    stages: [\n      { name: '数据接入', tag: '工况标注', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '异常标注', tag: '前兆段', dur: 4200, draw: function (t, g) { return F.stage2(t); } },\n      { name: '异常检测', tag: '异常分数', dur: 4800, draw: function (t, g) { return F.stage3(t); } },\n      { name: '不均衡处理', tag: '补少数类', dur: 4400, draw: function (t, g) { return F.stage4(t); } },\n      { name: '可解释预警', tag: '通道贡献', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '复核与回流', tag: '误报下降', dur: 4200, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的随钻多通道时序演示多变量异常检测、不均衡处理与可解释预警。","height":600};
  var META = {"id":"d2-hazard-warn","sceneId":"d2","title":"井下复杂事故前兆预警：不均衡样本 + 可解释预警"};
  var handle = null;
  var DEF = {"id":"d2-hazard-warn","sceneId":"d2","title":"井下复杂事故前兆预警：不均衡样本 + 可解释预警","methods":["ts"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"多通道时序","desc":"扭矩/立压/流量/转速 10+"},{"label":"标注成本","value":"高","desc":"异常样本极少、类不均衡"},{"label":"可见收益","value":"事故前兆预警","desc":"提前处置、降低误报"},{"label":"难度","value":"高","desc":"不均衡 + 可解释"}],"lede":"卡钻、井漏、溢流等井下复杂事故前，扭矩、立压、流量等随钻参数会出现异常前兆。传统靠经验阈值报警，误报漏报都高。智能方法用多变量异常检测从 10+ 通道抓前兆，但异常样本极少（类不均衡），且误报代价高、必须可解释。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>井下复杂事故（卡钻、井漏、溢流）爆发前，<b>扭矩、立压、流量、转速<\/b>这些随钻参数往往已有异常前兆。传统靠<b>经验阈值<\/b>报警——单通道超阈值就响，结果误报一堆、真事故又漏报。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>阈值报警误报高<\/b>——单通道超阈值，正常波动也触发，现场疲于应付<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>真前兆难抓<\/b>——事故前兆是多通道<b>组合<\/b>变化，单通道看不出<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>代价高<\/b>——漏报一次可能卡钻/井漏，损失巨大<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"阈值报警的问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">阈值报警：单通道超阈值 → 误报高、真前兆漏<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">经验阈值报警<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">盯单通道<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">超阈值报警<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">正常波动也触发<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">真前兆看不出<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">误报一堆 · 真事故漏报<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">现场疲于应付<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">为什么难<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 前兆是多通道组合变化<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 单通道阈值抓不住组合<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 漏报一次损失巨大<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">卡钻/井漏/溢流<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">真事故漏报代价极高<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「单通道阈值」换成「<b>多变量异常检测<\/b>」：从扭矩、立压、流量、转速等 <b>10+ 通道<\/b>抓异常前兆，输出一个综合异常分数；再处理<b>类不均衡<\/b>（异常样本极少），并给出<b>可解释<\/b>预警——哪几个通道、哪一段时序在报警。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>多变量异常检测<\/b>——多通道联合建模，抓组合前兆，替代单通道阈值<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>不均衡处理<\/b>——异常样本极少，用重采样/合成异常补少数类<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>可解释预警<\/b>——说明哪些通道/时刻触发，人才能信、敢处置<\/span><\/div><\/div><p>落地形态：事故前兆提前预警、误报降低，且每次报警都能说清「为什么」。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"多变量异常检测流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">多变量异常检测 + 不均衡 + 可解释<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">10+ 通道<\/text><path d=\"M36 78 C60 62 90 76 116 68\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">扭矩/立压/流量/转速<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">多变量异常检测<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">异常分数<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">抓组合前兆<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">不均衡处理<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">重采样/合成<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">补少数类<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">可解释预警<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">哪通道哪时刻<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">人敢处置<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">前兆提前预警 · 误报降低 · 每次报警说得清为什么<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>随钻多通道时序<\/b>：扭矩、立压、流量、转速等 10+ 通道，含正常与异常前兆段；<b>事故标签<\/b>：卡钻、井漏、溢流等事故发生点（极少）；<b>工况标注<\/b>：正常钻进、起下钻等，排除工况切换的假异常。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"事故预警数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">事故预警需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">随钻多通道时序<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">扭矩/立压/流量/转速 10+<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">含正常与异常前兆段<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">事故标签（极少）<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">卡钻/井漏/溢流发生点<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">类不均衡<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">工况标注<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">正常钻进/起下钻<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">排除工况切换假异常<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">处置结果反馈<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">预警后是否真发生事故<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">闭环校验误报<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：多变量异常检测 + 不均衡重采样 + 可解释 + 误报闭环<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>异常样本极少<\/b>——事故本身少，异常前兆样本类不均衡，模型偏向多数类<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>误报代价高<\/b>——一次误报要停工检查，代价大，但漏报更致命<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>需可解释<\/b>——黑盒报警现场不敢信、不敢处置，必须说清依据<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>多变量异常检测<\/b>（重建误差/隔离森林）把异常分数做出来；再加<b>不均衡处理<\/b>（重采样、SMOTE 合成异常）补少数类；最后加<b>可解释<\/b>（注意力/贡献度）让每次报警可追溯。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"事故预警难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 异常样本极少<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">类不均衡偏向多数类<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">重采样 / SMOTE<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">补少数类<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 误报代价高<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">误报停工、漏报致命<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">多变量重建误差<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">抓组合前兆降误报<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 需可解释<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">黑盒报警不敢信<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">注意力/贡献度<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">每次报警可追溯<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">多变量异常检测 → 不均衡处理 → 可解释预警<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一口井的井下复杂事故前兆预警改造","lead":["某井此前用单通道阈值报警，误报频繁、真前兆漏过。目标：用多变量异常检测从扭矩/立压/流量/转速等 10+ 通道抓事故前兆，处理类不均衡，给出可解释预警。","注意第 3、4、5 步：多变量异常检测、不均衡处理、可解释预警是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井","某生产井"],["通道数","10+（扭矩/立压等）"],["异常样本","极少·类不均衡"],["报警方式","单通道阈值"],["目标","多变量+可解释预警"],["误报代价","高·漏报更致命"]],"steps":[{"name":"多通道数据接入","role":"数据","do":"读入随钻多通道时序（扭矩/立压/流量/转速 10+），按工况标注正常钻进/起下钻。示范页屏 1 顶部可切换通道看时序。","effect":"一份按工况切分的多通道时序，作为异常检测输入。","trap":"不排除工况切换，把正常起下钻的参数变化当异常，误报爆表。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：多通道 → 工况标注<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">多通道时序<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">扭矩/立压/流量/转速<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">工况标注<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">正常钻进/起下钻<\/text><path d=\"M380 72 L404 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">排除假异常<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">工况切换不算异常<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：不排工况切换 → 正常起下钻当异常 → 误报爆表<\/text><\/svg>"},{"name":"异常前兆标注","role":"标注","do":"把卡钻/井漏/溢流发生点前的异常前兆段标注出来（极少）。示范页屏 1 顶部可注入异常看前兆形态。","effect":"少数异常前兆标签，供训练与验收。","trap":"异常样本太少又不想漏，把边界模糊的正常段也标成异常，模型更分不清。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">标注：事故点 → 异常前兆段（极少）<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">事故发生点<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">卡钻/井漏/溢流<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">前兆段标注<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">极少样本<\/text><path d=\"M380 72 L404 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">类不均衡<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">异常≈1%<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：边界模糊的正常段标成异常 → 模型更分不清<\/text><\/svg>"},{"name":"多变量异常检测","role":"算法核心","do":"用多变量异常检测（重建误差/隔离森林）从 10+ 通道算综合异常分数，替代单通道阈值。示范页屏 1 在浏览器里实时算异常分数。","effect":"一个能抓多通道组合前兆的异常检测器，替代单通道阈值。","trap":"只看单通道或只看均值，抓不住「多个通道同时小幅偏离」的组合前兆。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">异常检测：多通道 → 综合异常分数<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">多通道输入<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">10+ 通道<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">重建误差/隔离森林<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">多变量联合<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">综合异常分数<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">抓组合前兆<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只看单通道/均值 → 抓不住多通道同时小幅偏离的组合前兆<\/text><\/svg>"},{"name":"不均衡处理","role":"算法核心","do":"异常样本极少，用重采样（少数类上采样）或 SMOTE 合成异常补少数类，让模型不偏向多数类。示范页屏 2 展示不均衡处理前后的效果。","effect":"少数异常类被补足，模型不再一票否决式偏向正常。","trap":"SMOTE 合成异常太假，学到的是「合成异常」而非「真前兆」，真事故照漏。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">不均衡处理：重采样 / SMOTE 补少数类<\/text><rect x=\"24\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"109\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">原始：正常≈99% 异常≈1%<\/text><text x=\"109\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">模型偏向多数类<\/text><path d=\"M198 72 L222 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"226\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"301\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">重采样/SMOTE<\/text><text x=\"301\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">补少数类<\/text><path d=\"M380 72 L404 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">均衡后训练<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">异常不再被淹没<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：合成异常太假 → 学到「合成异常」非真前兆 → 真事故照漏<\/text><\/svg>"},{"name":"可解释预警","role":"算法核心","do":"给预警附解释：哪几个通道贡献大、哪一段时序触发，让人敢信敢处置。示范页屏 3 展示预警的通道贡献度。","effect":"每次报警能说清「为什么」，现场敢响应、能定位。","trap":"可解释是事后贴标签，没真正反映模型判断依据，会误导现场处置。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">可解释预警：报警 + 通道贡献 + 触发时刻<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">异常分数超阈值<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">触发预警<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">通道贡献度<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">立压↑ 流量↓<\/text><path d=\"M378 72 L400 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">现场可定位处置<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">说清为什么<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：可解释是事后贴标签 → 非真实判断依据 → 误导处置<\/text><\/svg>"},{"name":"误报复核与回流","role":"人工确认","do":"处理员对每次预警复核（真前兆/误报），结果反馈回模型。示范页屏 3 展示预警复核清单。","effect":"误报率持续下降，预警越来越可信，闭环校验。","trap":"复核不回流，模型不知道误报，误报率永远降不下来。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">复核：预警 → 真前兆/误报 → 回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">预警事件<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">异常分数超阈值<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">复核真伪<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">真前兆/误报<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">反馈回流<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">误报率持续降<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：复核不回流 → 模型不知道误报 → 误报率永远降不下来<\/text><\/svg>"}],"metrics":{"title":"怎么算「预警对了」","html":"<p>事故预警用 <b>召回率<\/b>（真前兆报出来多少）与 <b>误报率<\/b>（正常被误报多少）双重验收；<b>漏报<\/b>是最致命的——一次漏报可能卡钻/井漏。<\/p><p>最终还要看 <b>提前量<\/b>：预警是否在事故爆发前足够早给出，让现场有时间处置。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='事故预警效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>事故预警验收：召回率 × 误报率 × 提前量<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>预警效果<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>召回 55%<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>阈值报警<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>召回 90%<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>多变量异常<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>召回 ↑ 误报 ↓<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>提前量 + 可解释<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>提前 20 分钟<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>事故前预警<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>通道+时刻<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>可解释可追溯<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>漏报最致命 · 提前量要有<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 召回率 × 误报率 × 提前量<\/text><\/svg><\/p>"},"fails":[{"name":"异常样本极少","why":"事故本身少，异常前兆样本类不均衡，模型偏向多数类，真前兆被淹没。"},{"name":"误报代价高","why":"一次误报要停工检查，代价大；但漏报更致命，可能卡钻/井漏。"},{"name":"黑盒不可解释","why":"黑盒报警现场不敢信、不敢处置，必须说清依据。"},{"name":"复核不回流","why":"预警复核结果不反馈回模型，模型不知道误报，误报率永远降不下来。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的随钻多通道时序演示多变量异常检测、不均衡处理与可解释预警。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
